sys_variable_value.value:
(function execute(inputs, outputs) {
    
    var approverString = inputs.approver_list + '';
    
    gs.info('CLM DEBUG - Raw approver_list value: ' + approverString);
    gs.info('CLM DEBUG - Type: ' + typeof approverString);
    gs.info('CLM DEBUG - Index: ' + inputs.index);
    
    var approvers = approverString.split(',');
    gs.info('CLM DEBUG - Split count: ' + approvers.length);
    gs.info('CLM DEBUG - First entry: ' + approvers[0]);
    
    var filtered = [];
    for (var i = 0; i < approvers.length; i++) {
        if (approvers[i].trim() !== '') {
            filtered.push(approvers[i].trim());
        }
    }
    
    gs.info('CLM DEBUG - Filtered count: ' + filtered.length);
    gs.info('CLM DEBUG - Target entry: ' + filtered[inputs.index]);
    
    var userSysId = filtered[inputs.index];
    
    if (!userSysId) {
        gs.info('CLM DEBUG - No user found at index ' + inputs.index);
        return;
    }
    
    var gr = new GlideRecord('sys_user');
    if (gr.get(userSysId.trim())) {
        gs.info('CLM DEBUG - User found: ' + gr.user_name);
        outputs.current_approver = gr;
    } else {
        gs.info('CLM DEBUG - GlideRecord lookup failed for: ' + userSysId);
    }

})(inputs, outputs);

